path = [root.val]
def backtrack(root, target):
    remaining = target - root.val
    if not root.left and not root.right and remaining == 0:
        ans.append(path[:])
    for node in [root.left, root.right]:
        if node:
            path.append(node.val)
            backtrack(node, remaining)
            path.pop()
